PYTHONPATH=src python3 - <<'PY'
from inventory.stock import parse_qty

assert parse_qty(" 12 ") == 12
assert parse_qty("1") == 1

for text in ("0", "00", " -0 ", "-3", " -3 "):
    try:
        parse_qty(text)
    except ValueError:
        print(f"OK: parse_qty({text!r}) rejected")
    else:
        raise AssertionError(f"parse_qty({text!r}) should have raised ValueError")

try:
    parse_qty("twelve")
except ValueError:
    print("OK: parse_qty('twelve') rejected")
else:
    raise AssertionError("parse_qty('twelve') should have raised ValueError")
